    return envoyer(res, 200, "text/html", page("Nouveau produit", formulaire({}, [])));
  }
  if (req.method === "POST" && pathname === "/produits") {
    const donnees = Object.fromEntries(new URLSearchParams(await lireCorps(req)));
    const r = ajouter(donnees);
    if (!r.ok) return envoyer(res, 400, "text/html", page("Nouveau produit", formulaire(donnees, r.erreurs)));
    res.writeHead(303, { Location: "/produits/" + r.produit.id });
    return res.end();
  }
  const m = /^\/produits\/(\d+)$/.exec(pathname);
  const p = m && trouver(Number(m[1]));
  if (req.method === "GET" && p) {
    return envoyer(res, 200, "text/html", page(p.nom, `<p>Prix : ${p.prix} FCFA</p><p><a href="/">Retour</a></p>`));
  }
  envoyer(res, 404, "text/html", page("Introuvable", "<p>Cette page n’existe pas.</p>"));
});
